#include "tkl_i2c.h"
#include "tuya_error_code.h"
#include <ti/drivers/I2C.h>

// [DEPENDENCY INJECTION] Include Board Config
#include "tkl_board_config.h"

// Array to store handles for multiple I2C ports
// NO MAGIC NUMBER: Using constant from board config
static I2C_Handle g_i2c_handles[TKL_BOAD_MAX_I2C_PORTS] = {NULL};

// Helper to check validity
static bool is_valid_port(TUYA_I2C_NUM_E port) {
    return (port < TKL_BOAD_MAX_I2C_PORTS);
}
// --- END: user defines and implements ---

/**
 * @brief i2c init
 *
 * @param[in] port: i2c port
 * @param[in] cfg:  i2c config
 *
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */
OPERATE_RET tkl_i2c_init(TUYA_I2C_NUM_E port, const TUYA_I2C_BASE_CFG_T *cfg)
{
    // --- BEGIN: user implements ---
    if (!is_valid_port(port) || cfg == NULL) {
        return OPRT_INVALID_PARM;
    }

    // [MAPPING] Look up TI index dynamically
    int16_t ti_i2c_index = tkl_hw_get_i2c_index((uint8_t)port);

    // If result is negative, the Application did not map this I2C port.
    if (ti_i2c_index < 0) {
        return OPRT_NOT_SUPPORTED;
    }

    // Close existing if open
    if (g_i2c_handles[port] != NULL) {
        I2C_close(g_i2c_handles[port]);
        g_i2c_handles[port] = NULL;
    }

    I2C_Params params;
    I2C_Params_init(&params);

    // Set Bit Rate
    if (cfg->role == TUYA_I2C_ROLE_MASTER) {
        params.transferMode = I2C_MODE_BLOCKING;
        
        // Map Speed
        switch (cfg->speed) {
            case TUYA_I2C_SPEED_STANDARD: params.bitRate = I2C_100kHz; break;
            case TUYA_I2C_SPEED_FAST:     params.bitRate = I2C_400kHz; break;
            case TUYA_I2C_SPEED_HIGH:     params.bitRate = I2C_1000kHz; break; // I2C_3300kHz not supported on all TI devices
            default:                      params.bitRate = I2C_100kHz; break;
        }
    } else {
        // Slave mode logic would go here if supported
        return OPRT_NOT_SUPPORTED; 
    }

    // Initialize global driver
    I2C_init();

    // Open using Mapped Index
    g_i2c_handles[port] = I2C_open(ti_i2c_index, &params);

    if (g_i2c_handles[port] == NULL) {
        return OPRT_COM_ERROR;
    }

    return OPRT_OK;
    // --- END: user implements ---
}

/**
 * @brief i2c deinit
 *
 * @param[in] port: i2c port
 *
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */
OPERATE_RET tkl_i2c_deinit(TUYA_I2C_NUM_E port)
{
    // --- BEGIN: user implements ---
    if (!is_valid_port(port)) {
        return OPRT_INVALID_PARM;
    }

    if (g_i2c_handles[port] != NULL) {
        I2C_close(g_i2c_handles[port]);
        g_i2c_handles[port] = NULL;
    }

    return OPRT_OK;
    // --- END: user implements ---
}

